-- ============================================================================
-- D2: Machine Learning on Well Data joins the catalogue, the SECOND course of
-- the Data & AI module.
--
-- Catalogue row (module 'data_ai'; path_order 67, directly above D1
-- dataqc at 66; prereq_slug NULL, as D1 carries it: whether D2 requires D1 is
-- a go-live decision; school left at its default) plus the three capstones and
-- their eighteen graded fields, generated by
-- tools/course-waves/mlcore/gen_course.py from the ENGINE'S OWN RUN
-- (d2_capstone.mjs through the vendored engines/dataai/ml.js), which it refuses
-- to write unless fields.json carries exactly that run's values and the
-- tolerance gradedTolerance.js derives. Deep seeds are three separate
-- migrations; the go-live is a fifth and is HELD until a NextGen production
-- upload carries the route /dashboard/apps/mlcore, because the 78 lessons, the
-- teaching lab (mlcoreLab.js), its three explorer panels and the capstone case
-- files ship in the zip and not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. A model is a rule fitted to some wells and
-- judged on wells it has never seen, so the course teaches how to split by
-- whole wells, scale on the training rows, fit least squares and read what it
-- returns (Associate), how to penalise, cross-validate by wells, catch leakage
-- and score a classifier (Professional), and when the engine refuses, stops or
-- extrapolates (Expert), and grades each tier on its own question with numbers
-- the engine returns.
--
-- THE ENGINE. engines/dataai/ml.js, vendored sha-identical with
-- petrolord-engines 966bb9e (engines #252). Scaling is fitted on the training
-- rows with the population standard deviation; splits shuffle sorted well names
-- with one seeded mulberry32 stream; least squares and ridge refuse a scaled
-- condition number above 1e8; logistic regression tests for separation before
-- any Newton step and stops when the largest full step is at most tol.
--
-- WHAT IS GRADED. AKPARA (Associate) grades a training-row centre and scale, a
-- least squares coefficient and residual standard error, and the held-out
-- wells' RMSE and R-squared; OBORIA (Professional) grades a ridge coefficient,
-- a whole-well fold, the optimism of a random-row split, a logistic
-- coefficient, the F1 of pay and a test log loss; ISUAMA (Expert) grades a
-- scaled condition number, a penalised coefficient on separated rows, a
-- coefficient after three Newton updates, a permutation importance, a
-- learning-curve point and a written-back prediction. Every value is a return
-- value of the engine, and the data it was run on is in the case file the
-- prompt names.
--
-- All eighteen graded values were swept against every number the digest
-- prints and against every number handed to a learner in a prompt, a label or
-- a case file, at each field's own shipped tolerance: 0 collisions, and 0
-- pairwise. No prompt states another tier's graded value.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('mlcore', 'Machine Learning on Well Data', 'data_ai', 67, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'mlcore', 'beginner', 'associate',
  'AKPARA, 7 wells with a sonic, and a whole-well split',
  'A model and its test',
  'AKPARA, a field of 7 wells, AKPARA-1 to AKPARA-7, each logged at a one foot step. One case file comes with this capstone. akpara_wells.csv carries 168 rows, 24 a well, in well order and in depth order within each well: the well name, the depth in ft, GR in gAPI, RHOB in g/cm3, NPHI in v/v, RT in ohm.m, CALI in in, DT in us/ft, the core porosity PHIC in v/v and the PAY label, then the four well-level attributes, easting and northing in km, kb in m and mudWeight in ppg, each constant down its well. PAY is 1 when PHIC is at least 0.17 and RT is at least 11 ohm.m, and 0 otherwise. Every well has a sonic. The model is least squares with an intercept, target DT, features GR, RHOB and NPHI. Split the rows by whole wells with groupSplit at test fraction 0.3 and seed 11, and fit the scaler and the model on the training rows only. Report six values: the centre of RHOB fitted on the training rows, in g/cm3; the scale of GR fitted on the training rows, the population standard deviation, in gAPI; the NPHI coefficient of the fit, in us/ft per v/v; the residual standard error of the fit, in us/ft; the RMSE on the test wells, in us/ft; and the R-squared on the test wells, about the mean of the test targets. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','akpara_rhob_train_centre_g_cm3', 'label','The centre of RHOB fitted on the training rows', 'unit','g/cm3', 'expected',2.369333333333333, 'tol',5e-07),
    jsonb_build_object('key','akpara_gr_train_scale_gapi', 'label','The scale of GR fitted on the training rows, the population standard deviation', 'unit','gAPI', 'expected',18.445087772173302, 'tol',5e-07),
    jsonb_build_object('key','akpara_ols_nphi_coef_us_ft_per_vv', 'label','The NPHI coefficient of the least squares fit', 'unit','us/ft per v/v', 'expected',121.54669798581409, 'tol',5e-07),
    jsonb_build_object('key','akpara_ols_residual_se_us_ft', 'label','The residual standard error of the least squares fit', 'unit','us/ft', 'expected',4.3428711783541365, 'tol',5e-07),
    jsonb_build_object('key','akpara_test_rmse_us_ft', 'label','The RMSE on the test wells', 'unit','us/ft', 'expected',6.463037388177031, 'tol',5e-07),
    jsonb_build_object('key','akpara_test_r2', 'label','The R-squared on the test wells, about the mean of the test targets', 'unit','dimensionless', 'expected',0.5407700663135229, 'tol',5e-07)
  )
),
(
  'mlcore', 'intermediate', 'professional',
  'OBORIA, 8 wells with a sonic, well-level attributes and a stated pay rule',
  'Validating a model',
  'OBORIA, a field of 8 wells, OBORIA-1 to OBORIA-8, each logged at a one foot step. One case file comes with this capstone. oboria_wells.csv carries 200 rows, 25 a well, in well order and in depth order within each well: the well name, the depth in ft, GR in gAPI, RHOB in g/cm3, NPHI in v/v, RT in ohm.m, CALI in in, DT in us/ft, the core porosity PHIC in v/v and the PAY label, then the four well-level attributes, easting and northing in km, kb in m and mudWeight in ppg, each constant down its well. PAY is 1 when PHIC is at least 0.18 and RT is at least 12 ohm.m, and 0 otherwise. Every well has a sonic. Report six values. First, the GR coefficient, in us/ft per gAPI, of ridge at lambda 20, target DT, features GR, RHOB, NPHI, easting, northing, kb and mudWeight, fitted on the training rows of groupSplit at test fraction 0.25 and seed 3. Second, the test RMSE, in us/ft, of fold 2 of groupKFold with k 4 and seed 3, folds counted from 0 as the engine numbers them: least squares with an intercept, target DT, features GR, RHOB and NPHI, fitted on that fold''s training rows and scored on its test wells. Third, the optimism, in us/ft, that leakageDemo returns for least squares on GR, RHOB, NPHI and the four attributes, target DT, metric RMSE, at test fraction 0.25 and seed 3. Fourth, the RT coefficient, in log odds per ohm.m, of logistic regression of PAY on RHOB, NPHI and RT with no penalty, fitted on the training wells of groupSplit over all 8 wells at test fraction 0.25 and seed 9. Fifth, the F1 of pay, label 1, on that split''s test wells, with the engine''s class threshold. Sixth, the log loss on those test wells. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','oboria_ridge_gr_coef_us_ft_per_gapi', 'label','The GR coefficient of ridge at lambda 20', 'unit','us/ft per gAPI', 'expected',0.227314496133488, 'tol',5e-07),
    jsonb_build_object('key','oboria_fold2_test_rmse_us_ft', 'label','The test RMSE of fold 2 of the k-fold by wells, folds counted from 0', 'unit','us/ft', 'expected',5.561248670428681, 'tol',5e-07),
    jsonb_build_object('key','oboria_leak_optimism_rmse_us_ft', 'label','The optimism of the random-row split, in RMSE', 'unit','us/ft', 'expected',0.5236372597314727, 'tol',5e-07),
    jsonb_build_object('key','oboria_logistic_rt_coef_per_ohmm', 'label','The RT coefficient of the logistic fit, in log odds per ohm.m', 'unit','per ohm.m', 'expected',0.27888702512322944, 'tol',5e-07),
    jsonb_build_object('key','oboria_pay_f1', 'label','The F1 of pay, label 1, on the test wells', 'unit','dimensionless', 'expected',0.9032258064516129, 'tol',5e-07),
    jsonb_build_object('key','oboria_test_log_loss', 'label','The log loss on the test wells', 'unit','dimensionless', 'expected',0.13201570623027237, 'tol',5e-07)
  )
),
(
  'mlcore', 'advanced', 'expert',
  'ISUAMA, 9 wells, one of them without a sonic',
  'When the engine refuses, stops or extrapolates',
  'ISUAMA, a field of 9 wells, ISUAMA-1 to ISUAMA-9, each logged at a one foot step. One case file comes with this capstone. isuama_wells.csv carries 225 rows, 25 a well, in well order and in depth order within each well: the well name, the depth in ft, GR in gAPI, RHOB in g/cm3, NPHI in v/v, RT in ohm.m, CALI in in, DT in us/ft, the core porosity PHIC in v/v and the PAY label, then the four well-level attributes, easting and northing in km, kb in m and mudWeight in ppg, each constant down its well. PAY is 1 when PHIC is at least 0.17 and RT is at least 12 ohm.m, and 0 otherwise. ISUAMA-9 was logged without a sonic, and its DT is written null; every other well has one. Report six values. First, the scaled condition number of least squares with an intercept, target DT, features GR, RHOB, NPHI, easting, northing, kb and mudWeight, over every row with a sonic. Second, the PHIC coefficient, per v/v, of logistic regression of PAY on PHIC alone with l2 0.5, over the rows of all 9 wells with RT at or above 12 ohm.m. Third, the NPHI coefficient, per v/v, of logistic regression of PAY on RHOB, NPHI and RT over all 225 rows with no penalty and maxIter 3. Fourth, the mean drop in RMSE, in us/ft, that permutationImportance returns for NPHI with 5 repeats and seed 9, for least squares on GR, RHOB, NPHI and CALI, target DT, fitted on the training wells of groupSplit over the 8 wells with a sonic at test fraction 0.25 and seed 9, and scored on that split''s test wells. Fifth, the test RMSE, in us/ft, that learningCurve returns at three training wells for least squares on GR, RHOB and NPHI, target DT, over the 8 wells with a sonic, at test fraction 0.25 and seed 9, with trainGroupCounts 1, 2, 3, 4, 5, 6. Sixth, the DT, in us/ft, that ridge at lambda 5 on GR, RHOB and NPHI, fitted on every row with a sonic, predicts for row 0 of ISUAMA-9, its shallowest row, counting rows from 0. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','isuama_scaled_condition_attrs', 'label','The scaled condition number of the attribute design', 'unit','dimensionless', 'expected',1870.7743756649013, 'tol',5e-07),
    jsonb_build_object('key','isuama_l2_phic_coef_per_vv', 'label','The PHIC coefficient of the logistic fit at l2 0.5', 'unit','per v/v', 'expected',2.441453174361039, 'tol',5e-07),
    jsonb_build_object('key','isuama_nphi_coef_after_three_updates_per_vv', 'label','The NPHI coefficient after maxIter 3', 'unit','per v/v', 'expected',15.814859233201421, 'tol',5e-07),
    jsonb_build_object('key','isuama_perm_nphi_mean_drop_us_ft', 'label','The mean permutation drop of NPHI, in RMSE', 'unit','us/ft', 'expected',3.4745572800936713, 'tol',5e-07),
    jsonb_build_object('key','isuama_lc_test_rmse_three_wells_us_ft', 'label','The learning curve test RMSE at three training wells', 'unit','us/ft', 'expected',4.092026715190326, 'tol',5e-07),
    jsonb_build_object('key','isuama_pred_dt_first_row_us_ft', 'label','The predicted DT of row 0 of ISUAMA-9', 'unit','us/ft', 'expected',104.97106546670008, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
